acceptance-request.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "phax acceptance request",
  "$defs": {
    "NonEmptyString": {
      "type": "string",
      "description": "a non empty string",
      "title": "nonEmptyString",
      "minLength": 1
    }
  },
  "anyOf": [
    {
      "type": "object",
      "required": [
        "$schema",
        "verdict",
        "phase",
        "acceptancePhase",
        "base",
        "files"
      ],
      "properties": {
        "$schema": {
          "type": "string",
          "description": "The acceptance-request format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/acceptance-request/<X.Y.Z>.json",
          "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/acceptance-request\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
        },
        "verdict": {
          "type": "string",
          "enum": [
            "authored"
          ],
          "description": "Which judgment the provider gives: the acceptance phase's tests are authored."
        },
        "phase": {
          "type": "string",
          "description": "The gated phase.",
          "pattern": "^phase-\\d{2}$"
        },
        "acceptancePhase": {
          "type": "string",
          "description": "The pair's acceptance phase.",
          "pattern": "^phase-\\d{2}$"
        },
        "base": {
          "type": "string",
          "description": "The full object name of the commit the acceptance phase's branch was created from.",
          "pattern": "^[0-9a-f]{40}([0-9a-f]{24})?$"
        },
        "files": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/NonEmptyString"
          },
          "description": "The acceptance test files the pair declares, working-tree-root-relative paths in declaration order."
        }
      },
      "additionalProperties": false
    },
    {
      "type": "object",
      "required": [
        "$schema",
        "verdict",
        "phase",
        "acceptancePhase",
        "base",
        "acceptanceCommit",
        "files"
      ],
      "properties": {
        "$schema": {
          "type": "string",
          "description": "The acceptance-request format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/acceptance-request/<X.Y.Z>.json",
          "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/acceptance-request\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
        },
        "verdict": {
          "type": "string",
          "enum": [
            "passed"
          ],
          "description": "Which judgment the provider gives: the passing phase left no acceptance marker."
        },
        "phase": {
          "type": "string",
          "description": "The gated phase, the pair's passing phase.",
          "pattern": "^phase-\\d{2}$"
        },
        "acceptancePhase": {
          "type": "string",
          "description": "The pair's acceptance phase.",
          "pattern": "^phase-\\d{2}$"
        },
        "base": {
          "type": "string",
          "description": "The full object name of the commit the acceptance phase's branch was created from.",
          "pattern": "^[0-9a-f]{40}([0-9a-f]{24})?$"
        },
        "acceptanceCommit": {
          "type": "string",
          "description": "The full object name of the acceptance phase's commit, the one to judge against.",
          "pattern": "^[0-9a-f]{40}([0-9a-f]{24})?$"
        },
        "files": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/NonEmptyString"
          },
          "description": "The acceptance test files the pair declares, working-tree-root-relative paths in declaration order."
        }
      },
      "additionalProperties": false
    }
  ]
}

architecture-report.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "phax architecture report",
  "$defs": {
    "NonEmptyString": {
      "type": "string",
      "description": "a non empty string",
      "title": "nonEmptyString",
      "minLength": 1
    }
  },
  "type": "object",
  "required": [
    "$schema",
    "body",
    "parts"
  ],
  "properties": {
    "$schema": {
      "type": "string",
      "description": "The architecture-report format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/architecture-report/<X.Y.Z>.json",
      "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/architecture-report\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
    },
    "body": {
      "type": "string",
      "description": "Markdown for the agent to read. phax prints it as is, before the parts, and never parses it.",
      "title": "nonEmptyString",
      "minLength": 1
    },
    "parts": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "id",
          "name",
          "description",
          "globs"
        ],
        "properties": {
          "id": {
            "$ref": "#/$defs/NonEmptyString",
            "description": "The part's stable id, a kebab-case slug unique within the report. A phax.json bound names a part by it.",
            "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
          },
          "name": {
            "type": "string",
            "description": "The part's name, shown to the agent and never interpreted by phax.",
            "title": "nonEmptyString",
            "minLength": 1
          },
          "description": {
            "type": "string",
            "description": "One sentence on what the part holds.",
            "title": "nonEmptyString",
            "minLength": 1
          },
          "globs": {
            "type": "array",
            "minItems": 1,
            "items": {
              "$ref": "#/$defs/NonEmptyString",
              "description": "Checked by phax's parser: no leading /, backslash, brace, backtick or control character, no empty, . or .. segment, and ** only as a whole segment."
            },
            "description": "The files the part holds, as globs: working-tree-root-relative POSIX paths, matched case-sensitively and the same on every host. `**` as a whole segment matches zero or more segments, `*` matches zero or more characters within a segment, `?` matches one character other than `/`. A leading dot is not special. Every other character is literal, `[`, `]` and `!` included. Braces are refused. A glob covers files: write `src/core/**` to cover a directory."
          }
        },
        "additionalProperties": false
      },
      "description": "The parts of the code the report describes, possibly empty. No two parts share an id (checked by phax's parser). A part names no model or effort: the repository's owner binds those in phax.json."
    }
  },
  "additionalProperties": false
}

architecture-request.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "phax architecture request",
  "$defs": {
    "NonEmptyString": {
      "type": "string",
      "description": "a non empty string",
      "title": "nonEmptyString",
      "minLength": 1
    }
  },
  "type": "object",
  "required": [
    "$schema",
    "files"
  ],
  "properties": {
    "$schema": {
      "type": "string",
      "description": "The architecture-request format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/architecture-request/<X.Y.Z>.json",
      "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/architecture-request\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
    },
    "files": {
      "anyOf": [
