brief-record.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "phax brief record",
  "$defs": {
    "NonEmptyString": {
      "type": "string",
      "description": "a non empty string",
      "title": "nonEmptyString",
      "minLength": 1
    }
  },
  "type": "object",
  "required": [
    "$schema",
    "moment",
    "request",
    "outcome"
  ],
  "properties": {
    "$schema": {
      "type": "string",
      "description": "The brief-record format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/brief-record/<X.Y.Z>.json",
      "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/brief-record\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
    },
    "moment": {
      "type": "string",
      "enum": [
        "pushed",
        "pulled"
      ],
      "description": "pushed for the phase's brief at phase start (brief-00 only), pulled otherwise."
    },
    "request": {
      "anyOf": [
        {
          "type": "object",
          "required": [
            "$schema",
            "phase",
            "base",
            "terminal",
            "phases",
            "files"
          ],
          "properties": {
            "$schema": {
              "type": "string",
              "description": "The brief-request format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/brief-request/<X.Y.Z>.json",
              "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/brief-request\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
            },
            "phase": {
              "type": "string",
              "description": "The gated phase.",
              "pattern": "^phase-\\d{2}$"
            },
            "base": {
              "type": "string",
              "description": "The full object name of the commit the gated phase's branch was created from.",
              "pattern": "^[0-9a-f]{40}([0-9a-f]{24})?$"
            },
            "terminal": {
              "type": "boolean",
              "description": "True exactly when the gated phase is the run's terminal phase."
            },
            "phases": {
              "type": "array",
              "items": {
