                  "$ref": "#/$defs/LineNumber"
                },
                {
                  "$ref": "#/$defs/LineNumber"
                }
              ],
              "additionalItems": false
            },
            {
              "type": "null"
            }
          ],
          "description": "[start, end]: 1-based line numbers, both included, start at least 1 and end at least start. Null for the whole file."
        }
      },
      "additionalProperties": false,
      "description": "A file and the lines in it. Checked by phax's parser: lines starts at 1 or above and ends at or after its start."
    },
    "LineNumber": {
      "type": "integer",
      "description": "A 1-based line number.",
      "title": "int",
      "minimum": 1
    },
    "ReportRelatedLocation": {
      "type": "object",
      "required": [
        "file",
        "lines",
        "why"
      ],
      "properties": {
        "file": {
          "allOf": [
            {
              "$ref": "#/$defs/NonEmptyString"
            }
          ],
          "description": "A path relative to the working tree. phax never checks that it exists."
        },
        "lines": {
          "anyOf": [
            {
              "type": "array",
              "minItems": 2,
              "items": [
                {
                  "$ref": "#/$defs/LineNumber"
                },
                {
                  "$ref": "#/$defs/LineNumber"
                }
              ],
              "additionalItems": false
            },
            {
              "type": "null"
            }
          ],
          "description": "[start, end]: 1-based line numbers, both included, start at least 1 and end at least start. Null for the whole file."
        },
        "why": {
          "allOf": [
            {
              "$ref": "#/$defs/NonEmptyString"
            }
          ],
          "description": "Why the finding involves this location, in one line."
        }
      },
      "additionalProperties": false,
      "description": "Another location the finding involves, and why. Checked by phax's parser: lines starts at 1 or above and ends at or after its start."
    }
  },
  "type": "object",
  "required": [
    "$schema",
    "rules",
    "findings"
  ],
  "properties": {
    "$schema": {
      "type": "string",
      "description": "The brief-report format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/brief-report/<X.Y.Z>.json",
      "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/brief-report\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
    },
    "rules": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "rule",
          "files",
          "guide"
        ],
        "properties": {
          "rule": {
            "allOf": [
              {
                "$ref": "#/$defs/NonEmptyString"
              }
            ],
            "description": "What a file at these paths must or must not do, in plain words."
          },
          "files": {
            "type": "array",
            "minItems": 1,
            "items": {
              "$ref": "#/$defs/NonEmptyString"
            },
            "description": "The requested paths the rule covers, relative to the working tree, including files not written yet. At least one."
          },
          "guide": {
            "anyOf": [
              {
                "$ref": "#/$defs/ReportGuide"
              },
              {
                "type": "null"
              }
            ],
            "description": "How to comply with the rule: a summary and a file to read, or null when the provider gives none."
          }
        },
        "additionalProperties": false
      },
      "description": "The rules over the requested paths, in the provider's order, which is its rank. May be empty."
    },
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "id",
          "rule",
          "location",
          "message",
          "related",
          "guide",
          "due"
        ],
        "properties": {
          "id": {
            "allOf": [
              {
                "$ref": "#/$defs/NonEmptyString"
              }
            ],
            "description": "The provider's own id for the finding, stable across runs of the same check and unique within the report. phax compares it by equality only."
          },
          "rule": {
            "allOf": [
              {
                "$ref": "#/$defs/NonEmptyString"
              }
            ],
            "description": "The rule the finding breaks, in plain words."
          },
          "location": {
            "allOf": [
              {
                "$ref": "#/$defs/ReportLocation"
              }
            ],
            "description": "Where the finding is."
          },
          "message": {
            "allOf": [
              {
                "$ref": "#/$defs/NonEmptyString"
              }
            ],
            "description": "What was found, in one line."
          },
          "related": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/ReportRelatedLocation"
            },
            "description": "The other locations the finding involves, in the provider's order. May be empty."
          },
          "guide": {
            "anyOf": [
              {
                "$ref": "#/$defs/ReportGuide"
              },
              {
                "type": "null"
              }
            ],
            "description": "How to fix the finding: a summary and a file to read, or null when the provider gives none."
          },
          "due": {
            "anyOf": [
              {
                "type": "string",
                "enum": [
                  "this-phase",
                  "later"
                ]
              },
              {
                "type": "null"
              }
            ],
            "description": "The provider's word on when the finding must be closed: this-phase, later, or null when the request carried no phase facts. phax never computes or checks it."
          }
        },
        "additionalProperties": false
      },
      "description": "What fails at the requested paths, in the provider's order, which is its rank: each the rule it breaks, where, what was found, how to fix it and when. May be empty. Checked by phax's parser: no two findings share an id."
    }
  },
  "additionalProperties": false
}

