phase-record-manifest.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "phax phase record manifest",
  "$defs": {
    "NonEmptyString": {
      "type": "string",
      "description": "a non empty string",
      "title": "nonEmptyString",
      "minLength": 1
    },
    "SafeSessionId": {
      "type": "string",
      "description": "A provider session id: a letter or digit, then letters, digits, `.`, `_` or `-`. `.`, `..` and any slash are refused.",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*$"
    }
  },
  "type": "object",
  "required": [
    "$schema",
    "runId",
    "phaseId",
    "shape",
    "model",
    "effort",
    "provider",
    "userConfig",
    "outcome",
    "usage",
    "verifiedSurfaces",
    "acceptance",
    "mode",
    "stop"
  ],
  "properties": {
    "$schema": {
      "type": "string",
      "description": "The phase-record-manifest format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/phase-record-manifest/<X.Y.Z>.json",
      "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/phase-record-manifest\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
    },
    "runId": {
      "$ref": "#/$defs/NonEmptyString"
    },
    "phaseId": {
      "$ref": "#/$defs/NonEmptyString"
    },
    "shape": {
      "type": "string",
      "enum": [
        "full",
        "skeleton"
      ]
    },
    "sourceSha": {
      "$ref": "#/$defs/NonEmptyString"
    },
    "model": {
      "$ref": "#/$defs/NonEmptyString"
    },
    "effort": {
      "$ref": "#/$defs/NonEmptyString"
    },
    "provider": {
      "type": "string",
      "enum": [
        "claude-code",
        "codex-cli",
        "mistral-vibe"
      ]
    },
    "userConfig": {
      "type": "string",
      "enum": [
        "excluded",
        "loaded"
      ],
      "description": "Whether the operator's user-level provider configuration was loaded for the phase's headless sessions."
    },
    "outcome": {
      "type": "string",
      "enum": [
        "committed",
        "failed",
        "abandoned",
        "interrupted"
      ]
    },
    "usage": {
      "anyOf": [
        {
          "type": "object",
          "required": [
            "available",
            "usage"
          ],
          "properties": {
            "available": {
              "type": "boolean",
              "enum": [
