  "properties": {
    "$schema": {
      "type": "string",
      "description": "The phase-status format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/phase-status/<X.Y.Z>.json",
      "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/phase-status\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
    },
    "phaseId": {
      "$ref": "#/$defs/NonEmptyString"
    },
    "phaseIndex": {
      "type": "number"
    },
    "state": {
      "type": "string",
      "enum": [
        "pending",
        "setting_up_worktree",
        "running",
        "gates_failed",
        "gates_exhausted",
        "fixing",
        "failed",
        "passed",
        "committed",
        "cleaning_up",
        "cleaned_up",
        "review_open",
        "handoff_failed",
        "skipped",
        "rate_limited",
        "awaiting_review"
