run-list.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "phax run list",
  "$defs": {
    "NonEmptyString": {
      "type": "string",
      "description": "a non empty string",
      "title": "nonEmptyString",
      "minLength": 1
    },
    "Int": {
      "type": "integer",
      "description": "an integer",
      "title": "int"
    }
  },
  "type": "object",
  "required": [
    "$schema",
    "runs"
  ],
  "properties": {
    "$schema": {
      "type": "string",
      "description": "The run-list format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/run-list/<X.Y.Z>.json",
      "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/run-list\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
    },
    "runs": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "qualifiedName",
          "namespace",
          "shortName",
          "state",
          "branch",
          "currentPhase",
          "gateProfile",
          "updatedAt",
          "lockState",
          "recordsPending",
          "archivePath",
          "stop",
          "pullRequest"
        ],
        "properties": {
          "qualifiedName": {
            "type": "string",
            "description": "The run's qualified name: `<namespace>.<short name>`.",
            "title": "nonEmptyString",
            "minLength": 1
          },
          "namespace": {
            "type": "string"
          },
          "shortName": {
            "$ref": "#/$defs/NonEmptyString"
          },
          "state": {
            "type": "string",
            "enum": [
              "created",
              "running",
              "failed",
              "review_open",
              "completed",
              "stopped",
              "archived",
              "interrupted",
              "rate_limited",
              "awaiting_review"
            ]
          },
          "branch": {
            "type": "string"
          },
          "currentPhase": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "description": "The phase the run reached as `<n>/<total>`, or null when unknown."
          },
          "gateProfile": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "description": "The run's gate profile, or null when unknown."
          },
          "updatedAt": {
            "type": "string",
            "description": "The run's last update, as `YYYY-MM-DD HH:MM`."
          },
          "lockState": {
            "type": "string",
            "enum": [
              "none",
              "active",
              "stale"
            ]
          },
          "recordsPending": {
            "anyOf": [
              {
                "$ref": "#/$defs/Int",
                "description": "a non-negative number",
                "title": "greaterThanOrEqualTo(0)",
                "minimum": 0
              },
              {
                "type": "null"
              }
            ],
            "description": "The count of pending records, or null when records are off or not readable here."
          },
          "archivePath": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "description": "Where an archived run was moved, or null."
          },
          "stop": {
            "anyOf": [
              {
                "anyOf": [
                  {
                    "type": "object",
                    "required": [
                      "$schema",
                      "run",
                      "cause",
                      "state",
                      "phase",
                      "firstReading",
                      "worktree",
                      "seed",
                      "session",
                      "commands",
                      "lastClose",
                      "closeBase"
                    ],
                    "properties": {
                      "$schema": {
                        "type": "string",
                        "description": "The review-stop format's shape, named by the phax release that last changed it (not necessarily the release that wrote this file): https://docs.phax.run/schemas/review-stop/<X.Y.Z>.json",
                        "pattern": "^https:\\/\\/docs\\.phax\\.run\\/schemas\\/review-stop\\/(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.json$"
                      },
                      "run": {
                        "type": "string",
                        "description": "The run's qualified name.",
                        "title": "nonEmptyString",
                        "minLength": 1
                      },
                      "cause": {
                        "type": "string",
                        "enum": [
                          "declared"
                        ]
                      },
                      "state": {
                        "type": "string",
                        "enum": [
                          "awaiting_review"
                        ]
                      },
                      "phase": {
                        "type": "object",
                        "required": [
                          "id",
                          "title",
                          "mode",
                          "position",
                          "of"
                        ],
                        "properties": {
                          "id": {
                            "type": "string",
                            "description": "a string matching the pattern ^phase-\\d{2}$",
                            "pattern": "^phase-\\d{2}$"
                          },
